  6	/// The serialisation format for `AgentResponse::render`.
  7	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
  8	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
  9	#[non_exhaustive]
 10	pub enum OutputFormat {
 11	    /// Plain-text TOON / kv format. Default.
 12	    #[default]
 13	    Text,
 14	    /// Compact JSON object.
 15	    Json,
 16	}
 17	
 18	#[derive(Debug, Clone, PartialEq, Eq)]
 19	enum RenderTarget {
 20	    Unset,
 21	    Toon,
 22	    Kv,
 23	}
 24	
 25	/// Default per-cell truncation limit used by [`AgentResponse::new`].
 26	pub const DEFAULT_TRUNCATE_CELLS: usize = 200;
 27	
 28	/// Builder for an agent-facing response.
 29	#[derive(Debug, Clone)]
 30	#[non_exhaustive]
 31	pub struct AgentResponse {
 32	    type_name: String,
 33	    target: RenderTarget,
 34	    items: Vec<Vec<Value>>,
 35	    fields: Vec<String>,
 36	    single_item: Vec<KvItem>,
 37	    total_count: Option<usize>,
 38	    hints: Vec<Hint>,
 39	    recovery: Vec<RecoveryHint>,
 40	    truncate_cells_at: usize,
 41	    is_error: bool,
 42	    human_content: Option<String>,
 43	}
 44	
 45	impl AgentResponse {
 46	    /// Create a new, empty response for the given type name.
 47	    pub fn new(type_name: impl Into<String>) -> Self {
 48	        Self {
 49	            type_name: type_name.into(),
 50	            target: RenderTarget::Unset,
 51	            items: Vec::new(),
 52	            fields: Vec::new(),
 53	            single_item: Vec::new(),
 54	            total_count: None,
 55	            hints: Vec::new(),
 56	            recovery: Vec::new(),
 57	            truncate_cells_at: DEFAULT_TRUNCATE_CELLS,
 58	            is_error: false,
 59	            human_content: None,
 60	        }
 61	    }
 62	
 63	    /// Populate the TOON list path.
 64	    #[must_use]
 65	    pub fn items(mut self, rows: Vec<Vec<Value>>, fields: &[&str]) -> Self {
 66	        self.items = rows;
 67	        self.fields = fields.iter().map(|s| (*s).to_string()).collect();
 68	        self.target = RenderTarget::Toon;
 69	        self
 70	    }
 71	
 72	    /// Set the total available count.
 73	    #[must_use]
 74	    pub fn total_count(mut self, n: usize) -> Self {
 75	        self.total_count = Some(n);
 76	        self
 77	    }
 78	
 79	    /// Populate the KV single-item path.
 80	    #[must_use]
 81	    pub fn kv_items(mut self, items: Vec<KvItem>) -> Self {
 82	        self.single_item = items;
 83	        self.target = RenderTarget::Kv;
 84	        self
 85	    }
 86	
 87	    /// Append a contextual hint.
 88	    #[must_use]
 89	    pub fn hint(mut self, hint: impl Into<String>) -> Self {
 90	        self.hints.push(Hint::new(hint));
 91	        self
 92	    }
 93	
 94	    /// Replace all contextual hints.
 95	    #[must_use]
 96	    pub fn hints(mut self, hints: Vec<Hint>) -> Self {
 97	        self.hints = hints;
 98	        self
 99	    }
100	
101	    /// Append a recovery hint.
102	    #[must_use]
103	    pub fn recovery_hint(mut self, r: RecoveryHint) -> Self {
104	        self.recovery.push(r);
105	        self
106	    }
107	
108	    /// Set the max cell length before inline truncation on the TOON path.
109	    #[must_use]
110	    pub fn truncate_cells_at(mut self, limit: usize) -> Self {
111	        self.truncate_cells_at = limit;
112	        self
113	    }
114	
115	    /// Mark this response as an error state.
116	    #[must_use]
117	    pub fn as_error(mut self) -> Self {
118	        self.is_error = true;
119	        self
120	    }
121	
122	    /// Attach a human-facing companion block (`audience: user`).
123	    #[must_use]
124	    pub fn human_content(mut self, text: impl Into<String>) -> Self {
125	        self.human_content = Some(text.into());
126	        self
127	    }
128	
129	    fn toon_body(&self) -> String {
130	        let opts = michi_toon::ToonOptions::new(self.type_name.clone(), self.fields.clone(), self.items.clone())
131	            .total_count(self.total_count)
132	            .max_cell_len(self.truncate_cells_at);
133	        match opts.validate() {
134	            Ok(doc) => doc.render(),
135	            Err(e) => format!("error: toon_validation_failed\nmessage: {e}\n"),
136	        }
137	    }
138	
139	    fn kv_body(&self) -> String {
140	        crate::kv::render_kv(&self.single_item, self.total_count, &[])
141	    }
142	
143	    fn body(&self) -> String {
144	        match self.target {
145	            RenderTarget::Toon | RenderTarget::Unset => self.toon_body(),
146	            RenderTarget::Kv => self.kv_body(),
147	        }
148	    }
149	
150	    fn finish_text(&self, body: &str) -> String {
151	        let mut out = String::with_capacity(body.len() + self.hints.len() * 60 + self.recovery.len() * 80);
152	        out.push_str(body);
153	        crate::hints::append_hints(&mut out, &self.hints);
154	        crate::recovery::append_recovery(&mut out, &self.recovery);
155	        out
156	    }
157	
158	    /// Render the response in the requested format.
159	    #[must_use]
160	    pub fn render(&self, format: OutputFormat) -> String {
161	        match format {
162	            OutputFormat::Text => self.render_text(),
163	            OutputFormat::Json => self.render_json(),
164	        }
165	    }
166	
167	    /// Render via the TOON path.
168	    #[must_use]
169	    pub fn render_toon(&self) -> String {
170	        self.finish_text(&self.toon_body())
171	    }
172	
173	    /// Render via the KV path.
174	    #[must_use]
175	    pub fn render_kv(&self) -> String {
176	        self.finish_text(&self.kv_body())
177	    }
178	
179	    fn render_text(&self) -> String {
180	        self.finish_text(&self.body())
181	    }
182	
183	    /// Render just the `help[N]:` block for `self.hints`.
184	    #[must_use]
185	    pub fn render_hints_only(&self) -> String {
186	        crate::hints::render_hints(&self.hints)
187	    }
188	
189	    /// Render for the given audience.
190	    #[must_use]
191	    pub fn render_for(&self, audience: crate::audience::Audience) -> String {
192	        match audience {
193	            crate::audience::Audience::Assistant => self.render_text(),
194	            crate::audience::Audience::User => self.human_content.clone().unwrap_or_else(|| self.render_text()),
195	        }
196	    }
197	
198	    /// Whether `.human_content()` was set on this builder.
199	    #[must_use]
200	    pub fn has_human_content(&self) -> bool {
201	        self.human_content.is_some()
202	    }
203	
204	    /// Build the MCP `CallToolResult` for this response.
205	    #[must_use]
206	    pub fn to_call_tool_result(&self) -> crate::mcp::CallToolResult {
207	        let mut content = vec![crate::mcp::ContentBlock {
208	            text: self.render_text(),
209	            audience: vec![crate::audience::Audience::Assistant],
210	        }];
211	        if let Some(human) = &self.human_content {
212	            content.push(crate::mcp::ContentBlock {
213	                text: human.clone(),
214	                audience: vec![crate::audience::Audience::User],
215	            });
216	        }
217	        crate::mcp::CallToolResult {
218	            content,
219	            is_error: self.is_error,
220	            structured_content: self.render(OutputFormat::Json),
221	        }
222	    }
223	
224	    fn render_json(&self) -> String {
225	        let body = self.body();
226	        let capacity = body.len()
227	            + self.hints.iter().map(|h| h.as_str().len() + 16).sum::<usize>()
228	            + self.recovery.len() * 64
229	            + 64;
230	        let mut out = String::with_capacity(capacity);
231	        out.push_str("{\"body\":");
232	        json_string(&mut out, &body);
233	        out.push_str(",\"hints\":[");
234	        for (i, h) in self.hints.iter().enumerate() {
235	            if i > 0 {
236	                out.push(',');
237	            }
238	            json_string(&mut out, h.as_str());
239	        }
240	        out.push_str("],\"recovery\":[");
241	        for (i, r) in self.recovery.iter().enumerate() {
242	            if i > 0 {
243	                out.push(',');
244	            }
245	            out.push_str("{\"tool\":");
246	            json_string(&mut out, &r.tool);
247	            out.push_str(",\"params\":{");
248	            for (j, (k, v)) in r.params.iter().enumerate() {
249	                if j > 0 {
250	                    out.push(',');
251	                }
252	                json_string(&mut out, k);
253	                out.push(':');
254	                crate::kv::kv_value_to_json(&mut out, v);
255	            }
256	            out.push('}');
257	            if let Some(reason) = &r.reason {
258	                out.push_str(",\"reason\":");
259	                json_string(&mut out, reason);
260	            }
261	            out.push('}');
262	        }
263	        out.push_str("],\"isError\":");
264	        out.push_str(if self.is_error { "true" } else { "false" });
265	        out.push('}');
266	        out
267	    }
268	}
269	
270	fn json_string(out: &mut String, s: &str) {
271	    crate::kv::json_escape_str(out, s);
272	}
