  6	/// Classification of a `michi::Error` for routing and display decisions.
  7	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
  8	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
  9	#[non_exhaustive]
 10	pub enum ErrorClass {
 11	    /// The caller provided invalid input. Do not retry.
 12	    User,
 13	    /// A downstream or infrastructure failure that is not the caller's direct
 14	    /// error and is not expected to self-resolve without intervention. Note:
 15	    /// `RateLimited` falls here when `retryable: false` — the caller may have
 16	    /// contributed to the rate-limit condition, but at classification time the
 17	    /// error is not self-resolving. michi does not recommend automatic retry
 18	    /// for `Internal` errors.
 19	    Internal,
 20	    /// A transient failure expected to resolve without intervention.
 21	    Transient,
 22	}
