 40	/// The specific kind of domain error.
 41	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 42	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
 43	#[non_exhaustive]
 44	pub enum ErrorCode {
 45	    /// Bad parameters.
 46	    InvalidInput,
 47	    /// Resource absent.
 48	    NotFound,
 49	    /// Auth failure.
 50	    Unauthorized,
 51	    /// Permission denied.
 52	    Forbidden,
 53	    /// Resource state mismatch.
 54	    Conflict,
 55	    /// Rate limited (HTTP 429).
 56	    RateLimited,
 57	    /// Service unavailable (HTTP 503).
 58	    Unavailable,
 59	    /// Request timed out.
 60	    Timeout,
 61	    /// Downstream/external failure.
 62	    ExternalFailure,
 63	}
 64	
 65	impl ErrorCode {
 66	    /// The snake_case label used in rendered output.
 67	    #[must_use]
 68	    pub fn label(&self) -> &'static str {
 69	        match self {
 70	            Self::InvalidInput => "invalid_input",
 71	            Self::NotFound => "not_found",
 72	            Self::Unauthorized => "unauthorized",
 73	            Self::Forbidden => "forbidden",
 74	            Self::Conflict => "conflict",
 75	            Self::RateLimited => "rate_limited",
 76	            Self::Unavailable => "unavailable",
 77	            Self::Timeout => "timeout",
 78	            Self::ExternalFailure => "external_failure",
 79	        }
 80	    }
 81	
 82	    /// Whether this code is conventionally retryable.
 83	    #[must_use]
 84	    pub fn is_retryable_by_default(&self) -> bool {
 85	        matches!(self, Self::RateLimited | Self::Unavailable | Self::Timeout | Self::ExternalFailure)
 86	    }
 87	
 88	    /// The default [`ErrorClass`] for this code, independent of `DomainError.retryable`.
 89	    ///
 90	    /// Infrastructure codes (`RateLimited`, `Unavailable`, `Timeout`,
 91	    /// `ExternalFailure`) return `Internal`; caller-fault codes return `User`.
 92	    /// Used by [`Error::class()`].
 93	    #[must_use]
 94	    pub fn default_class(&self) -> ErrorClass {
 95	        match self {
 96	            Self::InvalidInput | Self::NotFound | Self::Unauthorized | Self::Forbidden | Self::Conflict => {
 97	                ErrorClass::User
 98	            }
 99	            Self::RateLimited | Self::Unavailable | Self::Timeout | Self::ExternalFailure => ErrorClass::Internal,
100	        }
101	    }
102	}
