104	/// A domain-level error.
105	#[derive(Debug, Clone)]
106	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
107	#[non_exhaustive]
108	pub struct DomainError {
109	    /// The error classification.
110	    pub code: ErrorCode,
111	    /// Human-readable message.
112	    pub message: String,
113	    /// Contextual hints, rendered as a trailing `help[N]:` block.
114	    pub hints: Vec<Hint>,
115	    /// Optional structured recovery hint.
116	    pub recovery: Option<RecoveryHint>,
117	    /// Whether this error is safe to retry.
118	    pub retryable: bool,
119	    /// Parsed `Retry-After` delay, if known.
120	    pub retry_after: Option<Duration>,
121	}
122	
123	impl DomainError {
124	    /// Create a domain error.
125	    pub fn new(code: ErrorCode, message: impl Into<String>) -> Self {
126	        Self {
127	            retryable: code.is_retryable_by_default(),
128	            code,
129	            message: message.into(),
130	            hints: Vec::new(),
131	            recovery: None,
132	            retry_after: None,
133	        }
134	    }
135	
136	    /// Append a contextual hint.
137	    #[must_use]
138	    pub fn hint(mut self, hint: impl Into<String>) -> Self {
139	        self.hints.push(Hint::new(hint));
140	        self
141	    }
142	
143	    /// Attach a structured recovery hint.
144	    #[must_use]
145	    pub fn recovery(mut self, r: RecoveryHint) -> Self {
146	        self.recovery = Some(r);
147	        self
148	    }
149	
150	    /// Override the default retryability for this error instance.
151	    #[must_use]
152	    pub fn retryable(mut self, retryable: bool) -> Self {
153	        self.retryable = retryable;
154	        self
155	    }
156	
157	    /// Attach a `Retry-After` delay.
158	    #[must_use]
159	    pub fn retry_after(mut self, d: Duration) -> Self {
160	        self.retry_after = Some(d);
161	        self
162	    }
163	
164	    /// The process exit code to use when this error is fatal. Always `1`.
165	    #[must_use]
166	    pub fn exit_code(&self) -> i32 {
167	        1
168	    }
169	
170	    /// Render to an agent-readable KV block with exit code, hints, and recovery.
171	    #[must_use]
172	    pub fn render(&self) -> String {
173	        let mut out = String::with_capacity(64 + self.message.len() + self.hints.len() * 50);
174	        out.push_str("error: ");
175	        out.push_str(self.code.label());
176	        out.push_str("\nmessage: ");
177	        out.push_str(&self.message);
178	        out.push_str("\nexit_code: 1\n");
179	        crate::hints::append_hints(&mut out, &self.hints);
180	        if let Some(r) = &self.recovery {
181	            crate::recovery::append_recovery(&mut out, std::slice::from_ref(r));
182	        }
183	        out
184	    }
185	
186	    /// Render formatted for GitHub Actions workflow annotations (`::error title=code::message`).
187	    ///
188	    /// Newlines and carriage returns are percent-encoded (`%0A`, `%0D`) to
189	    /// keep the annotation on a single line as required by the Actions runner.
190	    #[must_use]
191	    pub fn render_github_annotation(&self) -> String {
192	        format!("::error title={}::{}", self.code.label(), self.message.replace('\n', "%0A").replace('\r', "%0D"))
193	    }
194	
195	    /// Render as a JSON object matching `AgentResponse::render_json()` shape.
196	    ///
197	    /// Keys: `isError`, `error`, `message`, `retryable`, `hints`, `recovery`.
198	    /// Client code reading `structured_content` should not need two schemas.
199	    #[must_use]
200	    pub fn render_json(&self) -> String {
201	        let hints_est: usize = self.hints.iter().map(|h| h.as_str().len() + 4).sum();
202	        let recovery_est: usize = self.recovery.as_ref().map_or(0, |r| {
203	            50 + r.tool.len()
204	                + r.params.iter().map(|_| 20usize).sum::<usize>()
205	                + r.reason.as_ref().map_or(0, |s| s.len() + 12)
206	        });
207	        let mut out = String::with_capacity(128 + self.message.len() + hints_est + recovery_est);
208	        out.push_str("{\"isError\":true,\"error\":");
209	        crate::kv::json_escape_str(&mut out, self.code.label());
210	        out.push_str(",\"message\":");
211	        crate::kv::json_escape_str(&mut out, &self.message);
212	        out.push_str(",\"retryable\":");
213	        out.push_str(if self.retryable { "true" } else { "false" });
214	        out.push_str(",\"hints\":[");
215	        for (i, h) in self.hints.iter().enumerate() {
216	            if i > 0 {
217	                out.push(',');
218	            }
219	            crate::kv::json_escape_str(&mut out, h.as_str());
220	        }
221	        out.push_str("],\"recovery\":");
222	        match &self.recovery {
223	            None => out.push_str("null"),
224	            Some(r) => {
225	                out.push_str("{\"tool\":");
226	                crate::kv::json_escape_str(&mut out, &r.tool);
227	                out.push_str(",\"params\":{");
228	                for (j, (k, v)) in r.params.iter().enumerate() {
229	                    if j > 0 {
230	                        out.push(',');
231	                    }
232	                    crate::kv::json_escape_str(&mut out, k);
233	                    out.push(':');
234	                    crate::kv::kv_value_to_json(&mut out, v);
235	                }
236	                out.push('}');
237	                if let Some(reason) = &r.reason {
238	                    out.push_str(",\"reason\":");
239	                    crate::kv::json_escape_str(&mut out, reason);
240	                }
241	                out.push('}');
242	            }
243	        }
244	        out.push('}');
245	        out
246	    }
247	
248	    /// Build an MCP [`CallToolResult`] representing this error.
249	    ///
250	    /// Sets `is_error: true`. Text content uses [`DomainError::render()`];
251	    /// `structured_content` uses [`DomainError::render_json()`].
252	    ///
253	    /// **Canonical path:** call this directly when you hold a `DomainError`.
254	    /// Do not wrap in `AgentResponse::as_error()` — that loses typed fields.
255	    #[must_use]
256	    pub fn to_call_tool_result(&self) -> crate::mcp::CallToolResult {
257	        crate::mcp::CallToolResult {
258	            content: vec![crate::mcp::ContentBlock {
259	                text: self.render(),
260	                audience: vec![crate::audience::Audience::Assistant],
261	            }],
262	            is_error: true,
263	            structured_content: self.render_json(),
264	        }
265	    }
266	}
