277	impl miette::Diagnostic for DomainError {
278	    fn code<'a>(&'a self) -> Option<Box<dyn std::fmt::Display + 'a>> {
279	        Some(Box::new(self.code.label()))
280	    }
281	
282	    fn help<'a>(&'a self) -> Option<Box<dyn std::fmt::Display + 'a>> {
283	        if self.hints.is_empty() {
284	            None
285	        } else {
286	            Some(Box::new(self.hints.iter().map(|h| h.as_str()).collect::<Vec<_>>().join("\n")))
287	        }
288	    }
289	}
