291	/// The unified error type for the michi crate.
292	#[derive(Debug, thiserror::Error)]
293	#[non_exhaustive]
294	pub enum Error {
295	    /// Invalid or malformed input.
296	    #[error("Invalid input: {0}")]
297	    InvalidInput(String),
298	
299	    /// A required resource was not found.
300	    #[error("Not found: {0}")]
301	    NotFound(String),
302	
303	    /// A classified domain error with hints, recovery, and retry metadata.
304	    #[error("{}: {}", .0.code.label(), .0.message)]
305	    Domain(#[from] DomainError),
306	}
307	
308	impl Error {
309	    /// Render this error as an agent-readable plain-text string.
310	    #[must_use]
311	    pub fn render(&self) -> String {
312	        match self {
313	            Self::Domain(d) => d.render(),
314	            other => format!("error: {other}"),
315	        }
316	    }
317	
318	    /// The process exit code to use when this error is fatal.
319	    #[must_use]
320	    pub fn exit_code(&self) -> i32 {
321	        1
322	    }
323	
324	    /// Classify this error for routing decisions.
325	    #[must_use]
326	    pub fn class(&self) -> ErrorClass {
327	        match self {
328	            Self::Domain(d) if d.retryable => ErrorClass::Transient,
329	            Self::Domain(d) => d.code.default_class(),
330	            Self::InvalidInput(_) | Self::NotFound(_) => ErrorClass::User,
331	        }
332	    }
333	
334	    /// Whether this error is safe to retry automatically.
335	    #[must_use]
336	    pub fn is_retryable(&self) -> bool {
337	        matches!(self.class(), ErrorClass::Transient)
338	    }
339	}
