  3	/// A structured recovery hint for an agent encountering an error.
  4	#[derive(Debug, Clone, PartialEq)]
  5	#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
  6	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
  7	pub struct RecoveryHint {
  8	    /// The tool/operation name the agent should call to recover.
  9	    pub tool: String,
 10	    /// Ordered key-value parameters to call `tool` with.
 11	    pub params: Vec<(String, KvValue)>,
 12	    /// Optional human-readable reason this recovery path applies.
 13	    pub reason: Option<String>,
 14	}
 15	
 16	impl RecoveryHint {
 17	    /// Create a recovery hint naming just the tool to call.
 18	    pub fn new(tool: impl Into<String>) -> Self {
 19	        Self { tool: tool.into(), params: Vec::new(), reason: None }
 20	    }
 21	
 22	    /// Append a suggested parameter.
 23	    #[must_use]
 24	    pub fn param(mut self, key: impl Into<String>, value: KvValue) -> Self {
 25	        self.params.push((key.into(), value));
 26	        self
 27	    }
 28	
 29	    /// Attach a human-readable reason.
 30	    #[must_use]
 31	    pub fn reason(mut self, reason: impl Into<String>) -> Self {
 32	        self.reason = Some(reason.into());
 33	        self
 34	    }
 35	}
 36	
 37	/// Render a list of recovery hints as an agent-readable block.
 38	#[must_use]
 39	pub fn render_recovery(hints: &[RecoveryHint]) -> String {
 40	    if hints.is_empty() {
 41	        return String::new();
 42	    }
 43	    let capacity = 16 + hints.len() * 60;
 44	    let mut out = String::with_capacity(capacity);
 45	    append_recovery(&mut out, hints);
 46	    out
 47	}
 48	
 49	/// Append a `recovery[N]:` block to an existing string in-place.
 50	pub fn append_recovery(out: &mut String, hints: &[RecoveryHint]) {
 51	    if hints.is_empty() {
 52	        return;
 53	    }
 54	    out.push_str("recovery[");
 55	    out.push_str(&hints.len().to_string());
 56	    out.push_str("]:\n");
 57	    append_recovery_lines(out, hints);
 58	}
 59	
 60	pub(crate) fn append_recovery_lines(out: &mut String, hints: &[RecoveryHint]) {
 61	    for hint in hints {
 62	        out.push_str("  ");
 63	        out.push_str(&hint.tool);
 64	        if !hint.params.is_empty() {
 65	            out.push_str(": suggestedParams: { ");
 66	            for (i, (k, v)) in hint.params.iter().enumerate() {
 67	                if i > 0 {
 68	                    out.push_str(", ");
 69	                }
 70	                out.push_str(k);
 71	                out.push_str(": ");
 72	                crate::kv::push_kv_value(out, v);
 73	            }
 74	            out.push_str(" }");
 75	        }
 76	        if let Some(reason) = &hint.reason {
 77	            out.push_str(" — ");
 78	            out.push_str(reason);
 79	        }
 80	        out.push('\n');
 81	    }
 82	}
