  3	/// A structured recovery hint for an agent encountering an error.
  4	///
  5	/// With the `serde` feature it serializes to the same JSON as the structured companions of `AgentResponse` and
  6	/// `DomainError`: `{"tool": ..., "params": {key: value, ...}, "reason": ...}`, with `reason` omitted when absent and
  7	/// each parameter as a plain JSON value. Deserializing maps strings to `Text`, integers to `Int`, other numbers to
  8	/// `Float` (decimal places taken from the number), booleans to `Bool` and `null` to `Missing`.
  9	#[derive(Debug, Clone, PartialEq)]
 10	#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
 11	#[cfg_attr(feature = "serde", serde(into = "RecoveryHintWire", from = "RecoveryHintWire"))]
 12	pub struct RecoveryHint {
 13	    /// The tool/operation name the agent should call to recover.
 14	    pub tool: String,
 15	    /// Ordered key-value parameters to call `tool` with.
 16	    pub params: Vec<(String, KvValue)>,
 17	    /// Optional human-readable reason this recovery path applies.
 18	    pub reason: Option<String>,
 19	}
 20	
 21	impl RecoveryHint {
 22	    /// Create a recovery hint naming just the tool to call.
 23	    pub fn new(tool: impl Into<String>) -> Self {
 24	        Self { tool: tool.into(), params: Vec::new(), reason: None }
 25	    }
 26	
 27	    /// Append a suggested parameter.
 28	    #[must_use]
 29	    pub fn param(mut self, key: impl Into<String>, value: KvValue) -> Self {
 30	        self.params.push((key.into(), value));
 31	        self
 32	    }
 33	
 34	    /// Attach a human-readable reason.
 35	    #[must_use]
 36	    pub fn reason(mut self, reason: impl Into<String>) -> Self {
 37	        self.reason = Some(reason.into());
 38	        self
 39	    }
 40	}
 41	
 42	#[cfg(feature = "serde")]
 43	#[derive(serde::Serialize, serde::Deserialize)]
 44	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
 45	#[cfg_attr(feature = "schemars", schemars(rename = "RecoveryHint"))]
 46	struct RecoveryHintWire {
 47	    tool: String,
 48	    params: serde_json::Map<String, serde_json::Value>,
 49	    #[serde(default, skip_serializing_if = "Option::is_none")]
 50	    reason: Option<String>,
 51	}
 52	
 53	#[cfg(feature = "serde")]
 54	impl From<RecoveryHint> for RecoveryHintWire {
 55	    fn from(h: RecoveryHint) -> Self {
 56	        let params = h
 57	            .params
 58	            .iter()
 59	            .map(|(k, v)| {
 60	                // Same writer as the hand-built companions, so the two shapes cannot drift.
 61	                let mut json = String::new();
 62	                crate::kv::kv_value_to_json(&mut json, v);
 63	                (k.clone(), serde_json::from_str(&json).unwrap_or(serde_json::Value::String(json)))
 64	            })
 65	            .collect();
 66	        Self { tool: h.tool, params, reason: h.reason }
 67	    }
 68	}
 69	
 70	#[cfg(feature = "serde")]
 71	fn json_to_kv_value(v: serde_json::Value) -> KvValue {
 72	    match v {
 73	        serde_json::Value::Null => KvValue::Missing,
 74	        serde_json::Value::Bool(b) => KvValue::Bool(b),
 75	        serde_json::Value::String(s) => KvValue::Text(s),
 76	        serde_json::Value::Number(n) => match (n.as_i64(), n.as_f64()) {
 77	            (Some(i), _) => KvValue::Int(i),
 78	            (None, Some(f)) if n.is_f64() => {
 79	                let text = n.to_string();
 80	                let decimals = text.split_once('.').map_or(0, |(_, frac)| frac.len().min(20));
 81	                KvValue::Float(f, u8::try_from(decimals).unwrap_or(20))
 82	            }
 83	            _ => KvValue::Text(n.to_string()),
 84	        },
 85	        other => KvValue::Text(other.to_string()),
 86	    }
 87	}
 88	
 89	#[cfg(feature = "serde")]
 90	impl From<RecoveryHintWire> for RecoveryHint {
 91	    fn from(w: RecoveryHintWire) -> Self {
 92	        Self {
 93	            tool: w.tool,
 94	            params: w.params.into_iter().map(|(k, v)| (k, json_to_kv_value(v))).collect(),
 95	            reason: w.reason,
 96	        }
 97	    }
 98	}
