 1	//! Escaping shared by every renderer that writes caller text into line-oriented output.
 2	
 3	use std::borrow::Cow;
 4	
 5	/// Escape CR and LF as the two-character sequences `\r` and `\n`, so caller text can never start a new line and fake
 6	/// an extra field. Everything else, including backslashes, passes through unchanged.
 7	#[must_use]
 8	pub(crate) fn escape_line_breaks(s: &str) -> Cow<'_, str> {
 9	    if !s.contains(['\n', '\r']) {
10	        return Cow::Borrowed(s);
11	    }
12	    let mut out = String::with_capacity(s.len() + 8);
13	    for ch in s.chars() {
14	        match ch {
15	            '\n' => out.push_str("\\n"),
16	            '\r' => out.push_str("\\r"),
17	            _ => out.push(ch),
18	        }
19	    }
20	    Cow::Owned(out)
21	}
22	
23	#[cfg(test)]
24	mod tests {
25	    use super::*;
26	
27	    #[test]
28	    fn text_without_line_breaks_is_borrowed() {
29	        assert!(matches!(escape_line_breaks("plain, text"), Cow::Borrowed("plain, text")));
30	    }
31	
32	    #[test]
33	    fn cr_and_lf_become_visible_escapes() {
34	        assert_eq!(escape_line_breaks("a\r\nb\nc"), r"a\r\nb\nc");
35	    }
36	}

