  1	use crate::hints::Hint;
  2	use crate::kv::KvItem;
  3	use crate::recovery::RecoveryHint;
  4	use crate::toon::Value;
  5	
  6	/// The serialisation format for `AgentResponse::render`.
  7	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
  8	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
  9	#[non_exhaustive]
 10	pub enum OutputFormat {
 11	    /// Plain-text TOON / kv format. Default.
 12	    #[default]
 13	    Text,
 14	    /// Compact JSON object.
 15	    Json,
 16	}
 17	
 18	#[derive(Debug, Clone, PartialEq, Eq)]
 19	enum RenderTarget {
 20	    Unset,
 21	    Toon,
 22	    Kv,
 23	}
 24	
 25	/// Default per-cell truncation limit used by [`AgentResponse::new`].
 26	pub const DEFAULT_TRUNCATE_CELLS: usize = 200;
 27	
 28	/// Builder for an agent-facing response.
 29	#[derive(Debug, Clone)]
 30	#[non_exhaustive]
 31	pub struct AgentResponse {
 32	    type_name: String,
 33	    target: RenderTarget,
 34	    items: Vec<Vec<Value>>,
 35	    fields: Vec<String>,
 36	    single_item: Vec<KvItem>,
 37	    total_count: Option<usize>,
 38	    hints: Vec<Hint>,
 39	    recovery: Vec<RecoveryHint>,
 40	    truncate_cells_at: usize,
 41	    is_error: bool,
 42	    human_content: Option<String>,
 43	}
 44	
 45	impl AgentResponse {
 46	    /// Create a new, empty response for the given type name.
 47	    pub fn new(type_name: impl Into<String>) -> Self {
 48	        Self {
 49	            type_name: type_name.into(),
 50	            target: RenderTarget::Unset,
 51	            items: Vec::new(),
 52	            fields: Vec::new(),
 53	            single_item: Vec::new(),
 54	            total_count: None,
 55	            hints: Vec::new(),
 56	            recovery: Vec::new(),
 57	            truncate_cells_at: DEFAULT_TRUNCATE_CELLS,
 58	            is_error: false,
 59	            human_content: None,
 60	        }
 61	    }
 62	
 63	    /// Populate the TOON list path.
 64	    #[must_use]
 65	    pub fn items(mut self, rows: Vec<Vec<Value>>, fields: &[&str]) -> Self {
 66	        self.items = rows;
 67	        self.fields = fields.iter().map(|s| (*s).to_string()).collect();
 68	        self.target = RenderTarget::Toon;
 69	        self
 70	    }
 71	
 72	    /// Set the total available count.
 73	    #[must_use]
 74	    pub fn total_count(mut self, n: usize) -> Self {
 75	        self.total_count = Some(n);
 76	        self
 77	    }
 78	
 79	    /// Populate the KV single-item path.
 80	    #[must_use]
 81	    pub fn kv_items(mut self, items: Vec<KvItem>) -> Self {
 82	        self.single_item = items;
 83	        self.target = RenderTarget::Kv;
 84	        self
 85	    }
 86	
 87	    /// Append a contextual hint.
 88	    #[must_use]
 89	    pub fn hint(mut self, hint: impl Into<String>) -> Self {
 90	        self.hints.push(Hint::new(hint));
 91	        self
 92	    }
 93	
 94	    /// Replace all contextual hints.
 95	    #[must_use]
 96	    pub fn hints(mut self, hints: Vec<Hint>) -> Self {
 97	        self.hints = hints;
 98	        self
 99	    }
100	
101	    /// Append a recovery hint.
102	    #[must_use]
103	    pub fn recovery_hint(mut self, r: RecoveryHint) -> Self {
104	        self.recovery.push(r);
105	        self
106	    }
107	
108	    /// Set the max cell length before inline truncation on the TOON path.
109	    #[must_use]
110	    pub fn truncate_cells_at(mut self, limit: usize) -> Self {
111	        self.truncate_cells_at = limit;
112	        self
113	    }
114	
115	    /// Mark this response as an error state.
116	    #[must_use]
117	    pub fn as_error(mut self) -> Self {
118	        self.is_error = true;
119	        self
120	    }
121	
122	    /// Attach a human-facing companion block (`audience: user`).
123	    #[must_use]
124	    pub fn human_content(mut self, text: impl Into<String>) -> Self {
125	        self.human_content = Some(text.into());
126	        self
127	    }
128	
129	    /// The TOON body, and whether it is a validation-failure error block instead of the requested rows.
130	    fn toon_body(&self) -> (String, bool) {
131	        let opts = crate::toon::ToonOptions::new(self.type_name.clone(), self.fields.clone(), self.items.clone())
132	            .total_count(self.total_count)
133	            .max_cell_len(self.truncate_cells_at);
134	        match opts.validate() {
135	            Ok(doc) => (doc.render(), false),
136	            Err(e) => (format!("error: toon_validation_failed\nmessage: {e}\n"), true),
137	        }
138	    }
139	
140	    fn kv_body(&self) -> String {
141	        crate::kv::render_kv(&self.single_item, self.total_count, &[])
142	    }
143	
144	    /// The selected body, and whether this response is an error: set by `as_error()` or by a body that failed
145	    /// validation. Every output surface reads its error flag from here so text, JSON and MCP never disagree.
146	    fn body(&self) -> (String, bool) {
147	        match self.target {
148	            RenderTarget::Toon | RenderTarget::Unset => {
149	                let (body, failed) = self.toon_body();
150	                (body, failed || self.is_error)
151	            }
152	            RenderTarget::Kv => (self.kv_body(), self.is_error),
153	        }
154	    }
155	
156	    fn finish_text(&self, body: &str) -> String {
157	        let mut out = String::with_capacity(body.len() + self.hints.len() * 60 + self.recovery.len() * 80);
158	        out.push_str(body);
159	        crate::hints::append_hints(&mut out, &self.hints);
160	        crate::recovery::append_recovery(&mut out, &self.recovery);
161	        out
162	    }
163	
164	    /// Render the response in the requested format.
165	    #[must_use]
166	    pub fn render(&self, format: OutputFormat) -> String {
167	        match format {
168	            OutputFormat::Text => self.render_text(),
169	            OutputFormat::Json => self.render_json(),
170	        }
171	    }
172	
173	    /// Render via the TOON path.
174	    #[must_use]
175	    pub fn render_toon(&self) -> String {
176	        self.finish_text(&self.toon_body().0)
177	    }
178	
179	    /// Render via the KV path.
180	    #[must_use]
181	    pub fn render_kv(&self) -> String {
182	        self.finish_text(&self.kv_body())
183	    }
184	
185	    fn render_text(&self) -> String {
186	        self.finish_text(&self.body().0)
187	    }
188	
189	    /// Whether this response is an error: `as_error()` was called, or the TOON rows failed validation and the body
190	    /// is a `toon_validation_failed` error block.
191	    #[must_use]
192	    pub fn is_error(&self) -> bool {
193	        self.body().1
194	    }
195	
196	    /// Render just the `help[N]:` block for `self.hints`.
197	    #[must_use]
198	    pub fn render_hints_only(&self) -> String {
199	        crate::hints::render_hints(&self.hints)
200	    }
201	
202	    /// Render for the given audience.
203	    #[must_use]
204	    pub fn render_for(&self, audience: crate::audience::Audience) -> String {
205	        match audience {
206	            crate::audience::Audience::Assistant => self.render_text(),
207	            crate::audience::Audience::User => self.human_content.clone().unwrap_or_else(|| self.render_text()),
208	        }
209	    }
210	
211	    /// Whether `.human_content()` was set on this builder.
212	    #[must_use]
213	    pub fn has_human_content(&self) -> bool {
214	        self.human_content.is_some()
215	    }
216	
217	    /// Build the MCP `CallToolResult` for this response.
218	    #[must_use]
219	    pub fn to_call_tool_result(&self) -> crate::mcp::CallToolResult {
220	        let (body, is_error) = self.body();
221	        let mut content = vec![crate::mcp::ContentBlock {
222	            text: self.finish_text(&body),
223	            audience: vec![crate::audience::Audience::Assistant],
224	        }];
225	        if let Some(human) = &self.human_content {
226	            content.push(crate::mcp::ContentBlock {
227	                text: human.clone(),
228	                audience: vec![crate::audience::Audience::User],
229	            });
230	        }
231	        crate::mcp::CallToolResult { content, is_error, structured_content: self.json_from_body(&body, is_error) }
232	    }
233	
234	    fn render_json(&self) -> String {
235	        let (body, is_error) = self.body();
236	        self.json_from_body(&body, is_error)
237	    }
238	
239	    fn json_from_body(&self, body: &str, is_error: bool) -> String {
240	        let capacity = body.len()
241	            + self.hints.iter().map(|h| h.as_str().len() + 16).sum::<usize>()
242	            + self.recovery.len() * 64
243	            + 64;
244	        let mut out = String::with_capacity(capacity);
245	        out.push_str("{\"body\":");
246	        json_string(&mut out, body);
247	        out.push_str(",\"hints\":[");
248	        for (i, h) in self.hints.iter().enumerate() {
249	            if i > 0 {
250	                out.push(',');
251	            }
252	            json_string(&mut out, h.as_str());
253	        }
254	        out.push_str("],\"recovery\":[");
255	        for (i, r) in self.recovery.iter().enumerate() {
256	            if i > 0 {
257	                out.push(',');
258	            }
259	            out.push_str("{\"tool\":");
260	            json_string(&mut out, &r.tool);
261	            out.push_str(",\"params\":{");
262	            for (j, (k, v)) in r.params.iter().enumerate() {
263	                if j > 0 {
264	                    out.push(',');
265	                }
266	                json_string(&mut out, k);
267	                out.push(':');
268	                crate::kv::kv_value_to_json(&mut out, v);
269	            }
270	            out.push('}');
271	            if let Some(reason) = &r.reason {
272	                out.push_str(",\"reason\":");
273	                json_string(&mut out, reason);
274	            }
275	            out.push('}');
276	        }
277	        out.push_str("],\"isError\":");
278	        out.push_str(if is_error { "true" } else { "false" });
279	        out.push('}');
280	        out
281	    }
282	}
283	
284	fn json_string(out: &mut String, s: &str) {
285	    crate::kv::json_escape_str(out, s);
286	}
