     3	/// A structured recovery hint for an agent encountering an error.
     4	///
     5	/// With the `serde` feature it serializes to the same JSON as the structured companions of `AgentResponse` and
     6	/// `DomainError`: `{"tool": ..., "params": {key: value, ...}, "reason": ...}`, with `reason` omitted when absent and
     7	/// each parameter as a plain JSON value. Deserializing maps strings to `Text`, integers to `Int`, other numbers to
     8	/// `Float` (decimal places taken from the number), booleans to `Bool` and `null` to `Missing`.
     9	#[derive(Debug, Clone, PartialEq)]
    10	#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
    11	#[cfg_attr(feature = "serde", serde(into = "RecoveryHintWire", from = "RecoveryHintWire"))]
    12	pub struct RecoveryHint {
    13	    /// The tool/operation name the agent should call to recover.
    14	    pub tool: String,
    15	    /// Ordered key-value parameters to call `tool` with.
    16	    pub params: Vec<(String, KvValue)>,
    17	    /// Optional human-readable reason this recovery path applies.
    18	    pub reason: Option<String>,
    19	}
    20	
    21	impl RecoveryHint {
    22	    /// Create a recovery hint naming just the tool to call.
    23	    pub fn new(tool: impl Into<String>) -> Self {
    24	        Self { tool: tool.into(), params: Vec::new(), reason: None }
    25	    }
    26	
    27	    /// Append a suggested parameter.
    28	    #[must_use]
    29	    pub fn param(mut self, key: impl Into<String>, value: KvValue) -> Self {
    30	        self.params.push((key.into(), value));
    31	        self
    32	    }
    33	
    34	    /// Attach a human-readable reason.
    35	    #[must_use]
    36	    pub fn reason(mut self, reason: impl Into<String>) -> Self {
    37	        self.reason = Some(reason.into());
    38	        self
    39	    }
    40	}
