   112	/// Render a list of recovery hints as an agent-readable block.
   113	#[must_use]
   114	pub fn render_recovery(hints: &[RecoveryHint]) -> String {
   115	    if hints.is_empty() {
   116	        return String::new();
   117	    }
   118	    let capacity = 16 + hints.len() * 60;
   119	    let mut out = String::with_capacity(capacity);
   120	    append_recovery(&mut out, hints);
   121	    out
   122	}
   123	
   124	/// Append a `recovery[N]:` block to an existing string in-place.
   125	pub fn append_recovery(out: &mut String, hints: &[RecoveryHint]) {
   126	    if hints.is_empty() {
   127	        return;
   128	    }
   129	    out.push_str("recovery[");
   130	    out.push_str(&hints.len().to_string());
   131	    out.push_str("]:\n");
   132	    append_recovery_lines(out, hints);
   133	}
   134	
   135	pub(crate) fn append_recovery_lines(out: &mut String, hints: &[RecoveryHint]) {
   136	    for hint in hints {
   137	        out.push_str("  ");
   138	        out.push_str(&crate::text::escape_line_breaks(&hint.tool));
   139	        if !hint.params.is_empty() {
   140	            out.push_str(": suggestedParams: { ");
   141	            for (i, (k, v)) in hint.params.iter().enumerate() {
   142	                if i > 0 {
   143	                    out.push_str(", ");
   144	                }
   145	                out.push_str(&crate::text::escape_line_breaks(k));
   146	                out.push_str(": ");
   147	                crate::kv::push_kv_value(out, v);
   148	            }
   149	            out.push_str(" }");
   150	        }
   151	        if let Some(reason) = &hint.reason {
   152	            out.push_str(" — ");
   153	            out.push_str(&crate::text::escape_line_breaks(reason));
   154	        }
   155	        out.push('\n');
   156	    }
   157	}
