    fn text_without_line_breaks_is_borrowed() {
        assert!(matches!(escape_line_breaks("plain, text"), Cow::Borrowed("plain, text")));
    }

    #[test]
    fn cr_and_lf_become_visible_escapes() {
        assert_eq!(escape_line_breaks("a\r\nb\nc"), r"a\r\nb\nc");
    }
}

